<?php
namespace PharmaSure\Integrations\Services;
final class CallbackService{public function receive($tenant,$config_id,$provider_id,$event_type,$body,$timestamp,$signature){global $wpdb;$p=$wpdb->prefix.'ps_';$config=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$p}integration_configs WHERE id=%d AND tenant_id=%d AND status='active'",$config_id,$tenant),ARRAY_A);if(!$config||abs(time()-(int)$timestamp)>300){return new \WP_Error('invalid_callback','Callback configuration or timestamp is invalid.',array('status'=>401));}$credentials=(new CredentialVault())->decrypt($config['encrypted_credentials']);if(is_wp_error($credentials)||empty($credentials['callback_secret'])){return new \WP_Error('callback_secret_unavailable','Callback secret is not configured.',array('status'=>503));}$expected='sha256='.hash_hmac('sha256',$timestamp.'.'.$body,$credentials['callback_secret']);if(!hash_equals($expected,(string)$signature)){return new \WP_Error('invalid_signature','Callback signature is invalid.',array('status'=>401));}$provider_id=sanitize_text_field($provider_id);$existing=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$p}integration_callbacks WHERE tenant_id=%d AND config_id=%d AND provider_event_id=%s",$tenant,$config_id,$provider_id),ARRAY_A);if($existing){$existing['idempotent_replay']=true;return $existing;}$wpdb->insert($p.'integration_callbacks',array('tenant_id'=>$tenant,'config_id'=>$config_id,'provider_event_id'=>$provider_id,'event_type'=>sanitize_key($event_type),'payload'=>$body,'signature_valid'=>1,'processed_at'=>current_time('mysql',true),'status'=>'processed','created_at'=>current_time('mysql',true)));if(!$wpdb->insert_id){return new \WP_Error('callback_not_saved','Callback could not be recorded.',array('status'=>500));}$id=(int)$wpdb->insert_id;do_action('pharmasure_integration_callback',sanitize_key($event_type),(array)json_decode($body,true),$config);do_action('pharmasure_audit_log',array('tenant_id'=>$tenant,'action'=>'integration.callback_processed','object_type'=>'integration_callback','object_id'=>$id,'details'=>array('config_id'=>$config_id,'event_type'=>$event_type,'provider_event_id'=>$provider_id)));return array('id'=>$id,'status'=>'processed');}}
